const NEWS=[
 {h:"Cement makers cut prices as monsoon demand stays weak",t:"42 min ago",mins:42,src:"Dalal Daily",ns:3,filing:0,imp:3,read:"Bad for cement. Chandra Cement has the least room to absorb it.",st:[{id:"sk3",d:-1,why:"Least room to absorb lower prices."},{id:"u1",d:-1,why:"Tyre makers use the same trucks and roads budget."},{id:"sk7",d:-1,why:"Fewer loads to move."}]},
 {h:"Steel imports fall to a 2-year low after new duty",t:"2h ago",mins:120,src:"Market Ledger",ns:2,filing:0,imp:3,read:"Good for domestic steel makers. Helps Aarav Steel margins.",st:[{id:"sk1",d:1,why:"Margins improve."},{id:"sk9",d:1,why:"Cheaper local steel for parts."},{id:"u5",d:1,why:"More domestic cargo."}]},
 {h:"Brahma Pharma gets US approval for a new generic",t:"3h ago",mins:180,src:"Exchange filing",ns:1,filing:1,imp:2,read:"Mildly good. A small share of sales, so no change to our call.",st:[{id:"sk2",d:1,why:"Small share of sales."},{id:"u0",d:1,why:"Same sector mood."},{id:"u3",d:1,why:"Peers re-rated."}]},
 {h:"Power demand hits a seasonal high; spot prices up 9%",t:"5h ago",mins:300,src:"Dalal Daily",ns:2,filing:0,imp:2,read:"Good for power producers such as Falak Power.",st:[{id:"sk6",d:1,why:"Sells more at higher prices."},{id:"u0",d:1,why:"More cable demand."},{id:"sk5",d:-1,why:"Energy costs for factories."}]},
 {h:"Cotton prices ease for a second month",t:"Yesterday",mins:1000,src:"Market Ledger",ns:1,filing:0,imp:1,read:"Helps Dev Textiles costs, not enough yet to change the call.",st:[{id:"sk4",d:1,why:"Cheaper cotton."},{id:"u4",d:1,why:"Cheaper packaging inputs."},{id:"u2",d:1,why:"Paper pulp costs follow."}]},
 {h:"Interest rate decision due Friday; markets expect a hold",t:"Yesterday",mins:1100,src:"Rate Watch",ns:4,filing:0,imp:2,read:"A hold is already priced in. A cut would help banks and builders.",st:[{id:"u3",d:1,why:"Hotels borrow to expand."},{id:"sk5",d:1,why:"Cheaper credit to buyers."},{id:"sk3",d:1,why:"Builders buy more cement."}]}];
function score(n){const held=n.st.filter(x=>BY[x.id].held).length,why=[];let sc=n.imp*14;
 if(held){sc+=18+held*6;why.push(`You hold ${held}`)}if(n.filing){sc+=12;why.push("Company filing")}if(n.ns>1){sc+=Math.min(12,n.ns*3);why.push(n.ns+" sources")}
 const fr=Math.max(0,14-n.mins/60);sc+=fr;why.push(n.mins<60?n.mins+" min old":Math.round(n.mins/60)+" h old");
 const big=n.st.filter(x=>BY[x.id].v==="sell"||BY[x.id].v==="buy").length;if(big){sc+=big*4;why.push("Touches a call")}
 return{sc:Math.min(99,Math.round(sc)),why,imp:["","Low","Medium","High"][n.imp]}}
const ntile=(x,tag="a")=>{const s=BY[x.id];return `<a class="ntile ${x.d<0?"dn":""}" href="#stock-${s.id}" title="${esc(x.why||"")}"><span class="t1"><b class="trunc">${esc(s.nm)}</b>${chip(s.v)}</span>${spark(s)}<span class="t2"><span class="${x.d>0?"up":"dn"}" style="font-weight:700">${x.d>0?"▲ helps":"▼ hurts"}</span><span class="num ${s.day>=0?"up":"dn"}">${s.day>=0?"+":""}${s.day}%</span></span></a>`};
