const HID=new Set(); let toasts=[];
const jobById=id=>JOBS.find(j=>j.id===id);
const askState=a=>{const j=a.job&&jobById(a.job);return a.wait?["Waiting for the owner","v-watch"]:j?(j.state==="running"?["Being built","v-weak"]:["Done","v-buy"]):a.done?["Done","v-buy"]:["Sent","v-none"]};
function toast(html,cls,ms=8000){const t={html,cls:cls||"",id:Math.random()};toasts.push(t);paintToasts();if(ms)setTimeout(()=>{toasts=toasts.filter(x=>x!==t);paintToasts()},ms);return t}
function paintToasts(){$("#toasts").innerHTML=toasts.map(t=>`<div class="toast ${t.cls}"><span>${t.html}</span></div>`).join("")}
function runJob(j,after){const T=j.steps;j.step=0;const t=toast(`${esc(j.t)}: ${T[0]}`,"run",0),iv=setInterval(()=>{j.step++;if(j.step>=T.length){clearInterval(iv);j.state="done";j.took="1 min";j.when="just now";j.note="Finished just now";after?.(t);render();refreshBar();setTimeout(()=>{toasts=toasts.filter(x=>x!==t);paintToasts()},8000)}else{t.html=`${esc(j.t)}: step ${j.step+1} of ${T.length}, ${T[j.step]}`;paintToasts();refreshBar();if(route()[0]==="jobs")render()}},650)}
function newJob(o){const j={id:"j"+(++jid),state:"running",step:0,started:"just now",left:"about 3 min left",steps:STEPS,...o};JOBS.unshift(j);refreshBar();return j}
/* ---------- shell ---------- */
const NAV=[["today","wb_sunny","Today","Today"],["holdings","account_balance_wallet","Holdings","Holdings","desk"],["follow","star","Worth following","Follow"],["watchlist","visibility","Watchlist","Watch","desk"],["market","newspaper","Market & news","Market"],["funds","savings","Mutual funds","Funds","desk"]];
const NAVB=[["tax","receipt_long","Tax","Tax","desk"],["tradrec","history","Trading record","Trades","desk"],["record","fact_check","Our record","Record","desk"]];
const NAV2=[["jobs","schedule","Jobs","Jobs"],["feedback","rate_review","Feedback","Feedback","desk"],["health","monitor_heart","Health","Health","desk"],["settings","settings","Settings","Settings","desk"]];
const TABS=[...NAV,...NAVB,...NAV2].map(x=>x[0]);
const route=()=>{const h=location.hash.slice(1)||"today";return h.startsWith("stock-")?["stock",h.slice(6)]:[TABS.includes(h)?h:"today"]};
const SEL={today:"sk3",follow:"sk8",watchlist:"u0"},MODE={},FILT={},SCOPE={follow:"list"};
const cnt=k=>k==="follow"?unseenIds().filter(i=>BY[i].list==="follow").length:k==="today"?unseenIds().filter(i=>BY[i].list==="today").length:0;
function renderRail(){const [r,arg]=route(),cur=r==="stock"?(BY[arg]?.list==="follow"?"follow":BY[arg]?.list==="watchlist"?"watchlist":"today"):r,running=JOBS.filter(j=>j.state==="running").length;
 const a=([k,ic,l,ls,cls])=>`<a class="nav ${cls||""}" href="#${k}" ${cur===k?'aria-current="page"':""}><span class="ms">${ic}</span><span class="trunc lbl-l">${T(l)}</span><span class="trunc lbl-s">${T(ls)}</span>${k==="today"||k==="follow"?(cnt(k)?`<span class="cnt y num" title="Changed since you last looked">${cnt(k)}</span>`:k==="follow"?`<span class="cnt num">${listOf("follow").length}</span>`:k==="watchlist"?`<span class="cnt num">${WATCH.size}</span>`:""):k==="watchlist"?`<span class="cnt num">${WATCH.size}</span>`:k==="jobs"&&running?`<span class="cnt num" title="Running now">${running}</span>`:k==="health"?'<span class="cnt r num" title="Owner only: needs you">1</span>':""}</a>`;
 $("#rail").innerHTML=`<div class="brand"><canvas id="brand" width="80" height="80" style="width:40px;height:40px;border-radius:13px" aria-hidden="true"></canvas><span>stockpilot</span></div>${NAV.map(a).join("")}<div class="rail-div"></div>${NAVB.map(a).join("")}<button class="nav phone" data-more-nav style="border:0;background:none;cursor:pointer"><span class="ms">more_horiz</span><span>More</span></button><div class="rail-gap"></div><div class="rail-div"></div>${NAV2.map(a).join("")}<div class="rail-foot">Updated 09:50<br>Kite synced today</div>`;
 const c=$("#brand");if(c){const x=c.getContext("2d");x.scale(2,2);drawA(x,40)}}
function refreshBar(){const r=JOBS.find(j=>j.state==="running"&&j.kind==="Sync"),f=$(".fresh");if(f)f.innerHTML=r?`<b>Syncing…</b> step ${r.step+1} of ${r.steps.length}`:"Everything is up to date.";renderRail()}
function renderBar(){$("#bar").innerHTML=`<div class="search"><label for="q"><span class="ms">search</span><input id="q" role="combobox" aria-expanded="false" placeholder="${T("Search any stock")}" autocomplete="off"></label><ul class="sr" id="sr" role="listbox" hidden></ul></div><span class="fresh">Everything is up to date.</span><button class="btn t" id="top-sync"><span class="ms">sync</span>${T("Sync")}<span class="hn">${LANG==="bn"?"":" now"}</span></button><button class="btn o sm" id="lang" aria-label="Language"><span class="ms">translate</span>${LANG==="bn"?"English":"বাংলা"}</button><button class="icb" id="theme" aria-label="Dark or light" data-tip="Dark or light"><span class="ms">${document.documentElement.dataset.theme==="dark"?"light_mode":"dark_mode"}</span></button>`}
function lev(a,b){const m=[...Array(a.length+1)].map((_,i)=>[i,...Array(b.length).fill(0)]);for(let j=1;j<=b.length;j++)m[0][j]=j;for(let i=1;i<=a.length;i++)for(let j=1;j<=b.length;j++)m[i][j]=Math.min(m[i-1][j]+1,m[i][j-1]+1,m[i-1][j-1]+(a[i-1]===b[j-1]?0:1));return m[a.length][b.length]}
function searchShow(){const q=$("#q").value.trim().toLowerCase(),ul=$("#sr");if(!q){ul.hidden=true;$(".search").classList.remove("open");return}
 const sc=s=>{const n=(s.nm+" "+s.tk).toLowerCase();return n.includes(q)?0:Math.min(...n.split(/\s+/).map(w=>lev(w.slice(0,q.length+1),q)))};
 const r=U.map(s=>[sc(s),s]).filter(([d])=>d<=Math.max(1,Math.floor(q.length/3))).sort((a,b)=>a[0]-b[0]).slice(0,6);
 ul.innerHTML=r.length?r.map(([,s],i)=>`<li role="option" data-pick="${s.id}"><span><span class="nm">${esc(s.nm)}</span><br><span class="sy">${esc(s.tk)} · ${esc(s.sec)}</span></span><span class="tags"><span class="tag">${s.sme?"SME":"NSE"}</span></span></li>`).join(""):'<li><span class="sy">No match. Check the spelling.</span></li>';ul.hidden=false;$(".search").classList.add("open")}
/* ---------- list and pane ---------- */
const mtr=s=>`<span class="mt"><span class="mtr"><i style="left:${Math.min(96,Math.max(4,s.ch6))}%"></i></span><span class="mw t-${tone(s)}">${T(tone(s))}</span></span>`;
function lrow(key,s){return `<div class="lrow r-${s.v}" role="option" data-sel="${key}:${s.id}" aria-selected="${SEL[key]===s.id}" tabindex="0">${chip(s.v)}<span class="lm"><b class="trunc">${unseen(s.id)?'<span class="mk" title="Changed since you last looked"></span>':""}${esc(s.nm)}${NEWSONLY.has(s.id)&&!unseen(s.id)?'<span class="ms nws" title="News came in. Our view did not change.">newspaper</span>':""}</b><span class="ls trunc">${esc(s.tk)} · ${esc(s.sec)}</span></span><span class="lspc">${spark(s)}</span>${mtr(s)}${star(s)}</div>`}
const rowsFor=key=>{const q=(QF[key]||"").trim().toLowerCase(),c=CHIP[key]||"all";return listOf(key).filter(s=>(c==="all"||s.v===c)&&(!q||(s.nm+" "+s.tk).toLowerCase().includes(q)))};
function groups(key){const l=rowsFor(key),G=key==="today"?[["v","sell","Sell"],["v","weak","Weak"],["v","buy","Buy"],["v","hold","Keep"]]:key==="watchlist"?[["v","buy","Buy"],["v","hold","Keep"],["v","weak","Weak"],["v","watch","Watch"]]:[["grp","near","Closest to a buy"],["grp","out","Watch out for"]];
 const out=G.map(([f,v,lab])=>{const it=l.filter(s=>s[f]===v);return it.length?`<section class="lg" data-open="true"><button class="lgh r-${f==="v"?v:v==="near"?"buy":"watch"}" aria-expanded="true"><span class="ms car">expand_more</span><b>${T(lab)}</b><span class="n num">${it.length}</span></button><div class="lgr">${it.map(s=>lrow(key,s)).join("")}</div></section>`:""}).join("");
 return out||'<p class="muted" style="padding:24px">Nothing matches.</p>'}
const chbar=key=>{const ids=unseenIds().filter(i=>BY[i].list===key);return ids.length?`<div class="chbar"><span class="mk"></span><b title="Changed since you last looked">${ids.length} changed</b><button class="btn x sm markall">${T("Mark all seen")}</button></div>`:""};
function toolsRow(key,extra=""){const all=listOf(key),c=CHIP[key]||"all",vs=[...new Set(all.map(s=>s.v))],mode=MODE[key]||"split";
 const chips=[["all",all.length],...["sell","weak","review","buy","hold","watch"].filter(v=>vs.includes(v)).map(v=>[v,all.filter(s=>s.v===v).length])];
 return `<div class="tools"><span class="chipset">${chips.map(([k,n])=>`<button class="fchip" data-chip="${key}:${k}" aria-pressed="${c===k}">${k==="all"?T("All"):T(VL[k])} <span class="num">${n}</span></button>`).join("")}</span><label class="qf"><span class="ms" style="font-size:18px">search</span><input id="qf" data-key="${key}" value="${esc(QF[key]||"")}" placeholder="Filter this list" autocomplete="off"></label>${extra}<span class="seg2 vt">${[["split","List"],["table","Table"]].map(([m,l])=>`<button class="sg" data-mode="${key}:${m}" aria-pressed="${mode===m}">${T(l)}</button>`).join("")}</span></div>`}
function listPage(key,lead){const mode=MODE[key]||"split";
 if(mode==="table")return lead+tablePage(key);
 const rows=rowsFor(key),sel=rows.find(s=>s.id===SEL[key])||rows[0]||listOf(key)[0];SEL[key]=sel?.id;
 return `${lead}${toolsRow(key)}<div class="lp" data-key="${key}"><div class="lp-list" role="listbox">${chbar(key)}${groups(key)}</div><aside class="lp-pane" id="lpp" data-sym="${sel?.id||""}">${sel?detail(sel):'<p class="muted" style="padding:24px">Nothing to show.</p>'}</aside></div>`}
const FCH=[["pe","P/E under 25",s=>s.pe<25],["growth","Growth over 15%",s=>s.gr>15],["chance","Our chance 65%+",s=>s.ch6>=65],["size","Mid and large",s=>s.cap!=="Small"]];
function tablePage(key){const all=SCOPE[key]==="all"?U.filter(s=>!HIDDEN.has(s.id)):rowsFor(key),f=FILT[key]||{},rows=all.filter(s=>FCH.every(([k,,fn])=>!f[k]||fn(s))),tog=`<span class="seg2 vt">${[["split","List"],["table","Table"]].map(([m,l])=>`<button class="sg" data-mode="${key}:${m}" aria-pressed="${(MODE[key]||"split")===m}">${T(l)}</button>`).join("")}</span>`;
 return `<div class="tools">${FCH.map(([k,l])=>`<button class="fchip" data-f="${k}" aria-pressed="${!!f[k]}">${l}</button>`).join("")}<span class="seg2 vt" style="margin-left:auto">${(key==="follow"?[["list","Worth following"],["all","Every stock"]]:[["list","This list"],["all","Every stock"]]).map(([m,l])=>`<button class="sg" data-scope="${m}" aria-pressed="${(SCOPE[key]||"list")===m}">${l}</button>`).join("")}</span>${tog}</div>
 <table class="grid"><thead><tr><th><button>Stock</button></th><th><button>Call</button></th><th class="r"><button>Chance, 6 months</button></th><th class="r h1"><button>P/E</button></th><th class="r h1"><button>Growth</button></th><th class="h2"><button>Size</button></th><th class="r"><button>Price</button></th><th class="h3"><button>6 months</button></th></tr></thead><tbody>${rows.map(s=>`<tr class="r" data-open="${s.id}" tabindex="0"><td class="nm"><b>${unseen(s.id)?'<span class="mk"></span>':""}${esc(s.nm)}</b><div class="sy">${esc(s.tk)} · ${esc(s.sec)}</div></td><td>${chip(s.v)}</td><td class="r num">${s.ch6}%</td><td class="r num h1">${s.pe}</td><td class="r num h1">${s.gr}%</td><td class="h2">${s.cap}</td><td class="r num">${px(s.price)}</td><td class="h3"><span class="lsp">${spark(s)}</span></td></tr>`).join("")}</tbody></table><p class="muted" style="padding:10px 4px;font-size:13.5px">${rows.length} of ${all.length}${SCOPE[key]==="all"?" (example list; the real one covers every NSE, BSE and SME stock)":""}. This is the screener: filter any list here.</p>`}
const lead=(eb,h,p)=>`<header class="lead"><div class="lead-t"><span class="eyebrow">${eb}</span><h1>${h}</h1><p>${p}</p></div></header>`;
/* ---------- pages ---------- */
const PAGES={
 today(){return `${lead("Wednesday, 25 November 2026","Look at Chandra Cement first.","After that: Aarav Steel is a buy. Nothing else needs you today.")}${listPage("today","")}`},
 follow(){return listPage("follow",lead("Worth following",`${S.filter(s=>s.list==="follow").length} stocks to follow`,"Ideas and stocks to watch out for, in one list. Stocks you already hold are not here. Use Table to filter by P/E, growth or chance."))},
 watchlist(){return listPage("watchlist",lead("Watchlist","Stocks you picked","Your own list. Star any stock to add it here."))},
 stock(id){const s=BY[id]||S[0];return `<a class="btn x back" href="#${s.list==="follow"?"follow":s.list==="watchlist"?"watchlist":"today"}" data-back><span class="ms">arrow_back</span>Back</a>${detail(s,true)}`},
 market(){const L=NEWS.map(n=>({n,...score(n)})).sort((a,b)=>b.sc-a.sc),mine=[...new Set(NEWS.flatMap(n=>n.st).map(x=>x.id))].filter(i=>BY[i].held||BY[i].list==="today").slice(0,6);
  return `<header class="page-h"><h1 class="disp">Market &amp; news</h1><p>The market looks steady. Banks lead; cement and textiles are weak.</p></header>
  <div class="two"><div class="col" style="display:grid;gap:18px">
  <section><div class="eyebrow" style="margin:0 2px 8px">Your stocks in the news</div><div class="mine">${mine.map(i=>ntile({id:i,d:BY[i].day>=0?1:-1})).join("")}</div></section>
  <div class="mlist">${L.map(({n,sc,why,imp})=>`<article class="ncard" data-score="${sc}"><div class="nh"><span class="score" title="How much this matters to you, out of 100">Matters ${sc}<i><b style="width:${sc}%"></b></i></span><span>${imp} impact</span><span>${n.t}</span></div><div class="ntop"><h3>${esc(n.h)}</h3><span class="srcn">${n.src}</span></div><p class="read">${esc(n.read)}</p><div class="ntiles">${n.st.map(x=>ntile(x)).join("")}</div><div class="why-rank">${why.map((w,i)=>`<span class="${i===0&&/hold/.test(w)?"hl":""}">${esc(w)}</span>`).join("")}</div></article>`).join("")}</div></div>
  <aside class="side"><section class="panel"><h3 class="ph"><span>The market today</span></h3><div class="kv"><span class="k">Nifty 50</span><b class="up">26,182 +0.4%</b></div><div class="bigspark">${spark(BY.sk5,250)}</div><p style="font-size:14px;margin-top:6px">Steady. 64% of stocks are above their 10-month average.</p></section>
  <section class="panel"><h3 class="ph"><span>How the order is worked out</span></h3><ol class="rk"><li>How big the news is</li><li>Whether you hold a stock it touches</li><li>A company filing, or many sources</li><li>Fresh news ranks above old</li><li>Touches a stock we have a Buy or Sell on</li></ol></section>
  <section class="panel"><h3 class="ph"><span>Coming up</span></h3><div class="ev"><b class="num">27 Nov</b><span>Interest rate decision</span></div><div class="ev"><b class="num">12 Dec</b><span>Results: Chandra Cement, Brahma Pharma</span></div></section></aside></div>`},
 jobs(){const run=JOBS.filter(j=>j.state==="running"),rec=JOBS.filter(j=>j.state!=="running"),bad=JOBS.filter(j=>j.state==="failed").length;
  return `<header class="page-h"><h1 class="disp">Jobs</h1><p>Everything we are doing for you, running now and finished. Pressing a button anywhere starts a job and it shows here.</p></header>
  <div class="tiles"><div class="tile"><span class="k">Running now</span><span class="v">${run.length}</span><span class="s">${run.length?"Results appear on their own":"Nothing running"}</span></div><div class="tile"><span class="k">Done today</span><span class="v">${rec.filter(j=>j.state==="done").length}</span><span class="s">Last: ${esc(rec.find(j=>j.state==="done")?.t||"–")}</span></div><div class="tile"><span class="k">Did not finish</span><span class="v ${bad?"dn":""}">${bad}</span><span class="s">${bad?"Try again below":"All good"}</span></div><div class="tile"><span class="k">Model usage</span><span class="v">62%</span><span class="s">Resets in about 3 hours</span></div></div>
  <div class="secttl"><h2>Running</h2><span class="n num">${run.length}</span></div>
  <div class="jcards">${run.map(j=>`<div class="jcard"><div class="jt"><h3>${esc(j.t)}</h3><span class="status st-warn">Running</span></div><div class="steps">${j.steps.map((t,i)=>`<span class="step ${i<j.step?"done":i===j.step?"now":""}">${t}</span>`).join("")}</div><div class="jbar"><i style="width:${Math.round((j.step+.5)/j.steps.length*100)}%"></i></div><div class="jmeta"><span>Started ${j.started}</span><span>${j.left}</span>${j.ask?`<a class="jlink" href="#feedback"><span class="ms">rate_review</span>From your feedback</a>`:j.ref?`<a class="jlink" href="#stock-${j.ref}">${esc(BY[j.ref].nm)}</a>`:""}</div></div>`).join("")||'<p class="muted" style="padding:0 4px">Nothing running.</p>'}</div>
  <div class="secttl"><h2>Recent</h2><span class="n num">${rec.length}</span></div>
  <table class="grid"><thead><tr><th><button>Job</button></th><th class="h2"><button>Kind</button></th><th class="h1"><button>When</button></th><th class="h1"><button>Took</button></th><th><button>Result</button></th></tr></thead><tbody>${rec.map(j=>`<tr class="${j.state}"><td><b>${esc(j.t)}</b><div class="msg">${esc(j.note||"")}</div>${j.state==="failed"?'<div style="margin-top:6px"><button class="btn t sm retry">Try again</button></div>':""}</td><td class="h2">${j.kind}</td><td class="h1 num">${j.when}</td><td class="h1 num">${j.took||"–"}</td><td><span class="status ${j.state==="done"?"st-ok":"st-bad"}">${j.state==="done"?"Done":"Did not finish"}</span></td></tr>`).join("")}</tbody></table>`},
 feedback(){const L=ASKS.filter(x=>!HID.has(x.id));return `<header class="page-h"><h1 class="disp">Feedback</h1><p>Tell us anything you want changed. It starts a job straight away. Only the owner approves changes to a forecast, number, rule, money or tax.</p></header>
  <div class="fb-box"><textarea id="fbt" aria-label="Feedback" placeholder="Write what you want changed, in any language"></textarea><div><button class="btn f" data-fbsend><span class="ms">rate_review</span>Send</button></div></div>
  <div class="secttl"><h2>What you asked for</h2><span class="n num">${L.length}</span></div><div class="fblist">${L.map(a=>{const [st,cl]=askState(a),j=a.job&&jobById(a.job);return `<div class="fbitem" data-ask="${a.id}"><div class="top"><span class="chip ${cl}">${st}</span><span class="muted num" style="font-size:13px">${a.at}</span><button class="btn x sm del"><span class="ms">delete</span>Delete</button></div><p class="atext">${esc(a.t)}</p>${j?`<div class="jrow"><a class="jlink" href="#jobs"><span class="ms">schedule</span>Job</a><div>${j.state==="running"?`<div class="jbar"><i style="width:${Math.round((j.step+.5)/j.steps.length*100)}%"></i></div><span class="muted" style="font-size:12.5px">${j.steps[Math.min(j.step,j.steps.length-1)]}, ${j.left||""}</span>`:`<span class="muted">${esc(j.note||"Finished")}</span>`}</div><span class="status ${j.state==="done"?"st-ok":"st-warn"}">${j.state==="done"?"Done":"Running"}</span></div>`:""}</div>`}).join("")}</div>`},
 holdings(){return stub("Holdings","Unchanged from v10, with the new yellow marks.")},tax(){return stub("Tax","Unchanged from v10.")},tradrec(){return stub("Trading record","Unchanged from v10.")},record(){return stub("Our record","Unchanged from v10: our forecasts, and how they did.")},funds(){return stub("Mutual funds","Slice (c). Same list and detail layout as stocks.")},health(){return stub("Health","Redesigned later. The red count on the nav shows for the owner only.")},
 settings(){return `<header class="page-h"><h1 class="disp">Settings</h1><p>Other settings are unchanged from v10.</p></header><section class="pane"><div class="blk"><h3>App icon</h3><div style="display:flex;gap:18px;align-items:center;flex-wrap:wrap"><canvas class="ico" width="192" height="192" style="width:96px;height:96px;border-radius:22px"></canvas><div class="muted" style="max-width:46ch">Direction A, the amber rising line. It shows on the browser tab, bright against any tab strip, light or dark.</div></div><div class="tabprev">${["l","d"].map(m=>`<div class="tabstrip ${m}"><canvas class="tab16" width="16" height="16" style="width:16px;height:16px"></canvas><span>stockpilot</span></div><div class="tabstrip ${m}"><canvas class="tab32" width="32" height="32" style="width:32px;height:32px"></canvas><span>32 px tab</span></div>`).join("")}</div></div></section>`}};
const stub=(t,m)=>`<header class="page-h"><h1 class="disp">${t}</h1><p>${m}</p></header>`;
/* ---------- icon A ---------- */
function drawA(c,s){c.fillStyle="#FFB300";c.beginPath();c.roundRect(0,0,s,s,s*.22);c.fill();c.strokeStyle="#1B1300";c.lineWidth=s*.13;c.lineCap=c.lineJoin="round";c.beginPath();c.moveTo(s*.18,s*.7);c.lineTo(s*.4,s*.5);c.lineTo(s*.55,s*.62);c.lineTo(s*.82,s*.28);c.stroke();c.fillStyle="#1B1300";c.beginPath();c.moveTo(s*.86,s*.2);c.lineTo(s*.86,s*.42);c.lineTo(s*.64,s*.2);c.fill()}
function paintIcons(){$$("canvas.tab16,canvas.tab32,canvas.ico").forEach(cv=>{const s=cv.classList.contains("tab16")?16:cv.classList.contains("tab32")?32:96,r=Math.max(1,Math.round(devicePixelRatio||1))*(s===96?2:1);cv.width=cv.height=s*r;const c=cv.getContext("2d");c.scale(r,r);drawA(c,s)})}
function favicon(){const c=document.createElement("canvas");c.width=c.height=32;drawA(c.getContext("2d"),32);let l=document.querySelector("link[rel=icon]");if(!l){l=document.createElement("link");l.rel="icon";document.head.append(l)}try{l.href=c.toDataURL()}catch{}}
/* ---------- render ---------- */
function setTitle(){const n=unseenIds().length;document.title=(n?`(${n}) `:"")+"stockpilot"}
function render(){const [r,arg]=route(),keep=$(".lp-list")?.scrollTop,pk=$("#lpp")?.scrollTop;$("#view").innerHTML=(PAGES[r]||PAGES.today)(arg);
 $("#app").classList.toggle("shell",!!$(".lp")&&innerWidth>900);setTitle();renderRail();if(r==="settings")paintIcons();
 $$("[data-chart]").forEach(b=>{const s=BY[b.dataset.chart];drawChart(b,s);new ResizeObserver(()=>drawChart(b,s)).observe($(".cv",b))});
 const l=$(".lp-list");if(l&&keep)l.scrollTop=keep;const p=$("#lpp");if(p&&pk)p.scrollTop=pk}
const selectRow=(key,id)=>{SEL[key]=id;seen.add(id);$$("[data-sel]").forEach(el=>el.setAttribute("aria-selected",String(el.dataset.sel===key+":"+id)));
 const p=$("#lpp");p.dataset.sym=id;p.innerHTML=detail(BY[id]);p.scrollTop=0;$$("[data-chart]").forEach(b=>{drawChart(b,BY[id]);new ResizeObserver(()=>drawChart(b,BY[id])).observe($(".cv",b))});
 const row=$(`[data-sel="${key}:${id}"] .mk`);row?.remove();setTitle();renderRail();const cb=$(".chbar");if(cb)cb.outerHTML=chbar(key)};
document.addEventListener("click",e=>{const el=s=>e.target.closest(s);let x;
 if((x=el("[data-star]"))){e.stopPropagation();const id=x.dataset.star,was=WATCH.has(id);was?WATCH.delete(id):WATCH.add(id);render();toast(`${was?"Removed from":"Added to"} your watchlist. <a href="#" data-unstar="${id}:${was?1:0}">Undo</a>`);return}
 if((x=el("[data-unstar]"))){e.preventDefault();const [id,w]=x.dataset.unstar.split(":");w==="1"?WATCH.add(id):WATCH.delete(id);toasts=toasts.filter(t=>!t.html.includes("data-unstar"));paintToasts();render();return}
 if((x=el("[data-hide]"))){const [id,d]=x.dataset.hide.split(":");HIDDEN.add(id);render();toast(`${esc(BY[id].nm)} hidden${d==="30"?" for 30 days":" for good"}. <a href="#" data-unhide="${id}">Undo</a>`);return}
 if((x=el("[data-unhide]"))){e.preventDefault();HIDDEN.delete(x.dataset.unhide);toasts=toasts.filter(t=>!t.html.includes("data-unhide"));paintToasts();render();return}
 if((x=el("[data-chip]"))){const [k,v]=x.dataset.chip.split(":");CHIP[k]=v;render();return}
 if((x=el("[data-z]"))){const id=el("[data-chart]").dataset.chart,v=VIEW[id],c=(v.a+v.b)/2,h=(v.b-v.a)/2,k=x.dataset.z;
  if(k==="reset")VIEW[id]={a:N-252,b:N-1};else{const f=k==="in"?.7:1.4;let a=c-h*f,b=c+h*f;if(b-a<10){a=c-5;b=c+5}if(b>N-1){a-=b-(N-1);b=N-1}if(a<0){b-=a;a=0}VIEW[id]={a,b:Math.min(b,N-1)}}render();return}
 if((x=el("[data-pick]"))){location.hash="stock-"+x.dataset.pick;$("#q").value="";$("#sr").hidden=true;return}
 if((x=el("[data-sel]"))){const [k,id]=x.dataset.sel.split(":");if(innerWidth<=900){seen.add(id);location.hash="stock-"+id;return}return selectRow(k,id)}
 if(el(".markall")){unseenIds().forEach(i=>seen.add(i));render();return}
 if(el("[data-layers]")){LO=!LO;render();return}
 if((x=el(".rng"))){const s=BY[x.closest("[data-chart]").dataset.chart];VIEW[s.id]={a:N-RN[x.dataset.r],b:N-1};render();return}
 if((x=el("[data-tg]"))){TG[x.dataset.tg]=TG[x.dataset.tg]?0:1;render();return}
 if(el(".shut")){const b=el(".chart");b.classList.remove("isfull");drawChart(b,BY[b.dataset.chart]);return}
 if(el(".full")){const b=el(".sec").querySelector(".chart");b.classList.toggle("isfull");drawChart(b,BY[b.dataset.chart]);return}
 if((x=el(".update,.analyse"))){const s=BY[x.dataset.id],j=newJob({t:(x.classList.contains("update")?"Update forecast: ":"Analyse ")+s.nm,kind:"Analyse",ref:s.id});runJob(j,()=>{s.ood=0;CH.push({id:s.id,at:"Just now",from:"Keep",to:VL[s.v],pf:s.ch6,pt:s.ch6,why:"The forecast you asked for is ready."});seen.delete(s.id);toast(`${esc(s.nm)} forecast is ready – <a href="#stock-${s.id}">Open</a>`,"done")});render();return}
 if(el(".retry")){const j=JOBS.find(j=>j.state==="failed");j.state="running";j.t=j.t;j.steps=STEPS;j.started="just now";j.left="about 3 min left";runJob(j,()=>{const s=BY[j.ref];if(s)s.ood=0;toast(`${esc(s?.nm||j.t)} forecast is ready – <a href="#stock-${j.ref}">Open</a>`,"done")});render();return}
 if(el("#top-sync")){if(JOBS.some(j=>j.state==="running"&&j.kind==="Sync"))return;const j=newJob({t:"Sync from Zerodha",kind:"Sync",steps:["Queued","Sign in","Holdings","Trades","Done"]});runJob(j,()=>toast('Sync finished – <a href="#jobs">Open</a>',"done"));refreshBar();return}
 if(el("[data-fbsend]")){const t=$("#fbt").value.trim();if(!t){$("#fbt").focus();return}const a={id:"a"+(++jid),t,at:"Just now",job:null},j=newJob({t:"Build: "+t.slice(0,48),kind:"Feedback",ask:a.id,steps:["Queued","Plan","Build","Test","Publish"]});a.job=j.id;ASKS.unshift(a);runJob(j,()=>toast('Your change is live – <a href="#feedback">See it</a>',"done"));render();return}
 if((x=el(".del"))){const id=x.closest(".fbitem").dataset.ask;HID.add(id);render();toast(`Removed. <a href="#" data-undo="${id}">Undo</a>`);return}
 if((x=el("[data-undo]"))){e.preventDefault();HID.delete(x.dataset.undo);toasts=toasts.filter(t=>!t.html.includes("data-undo"));paintToasts();render();return}
 if((x=el("[data-f]"))){const k=route()[0],f=FILT[k]??={};f[x.dataset.f]=!f[x.dataset.f];render();return}
 if((x=el("[data-scope]"))){SCOPE[route()[0]]=x.dataset.scope;render();return}
 if((x=el("[data-mode]"))){const [k,m]=x.dataset.mode.split(":");MODE[k]=m;render();return}
 if((x=el("tr[data-open]"))){location.hash="stock-"+x.dataset.open;return}
 if((x=el(".lgh"))){const g=x.closest(".lg");g.dataset.open=g.dataset.open==="true"?"false":"true";x.setAttribute("aria-expanded",g.dataset.open);return}
 if(el("#lang")){LANG=LANG==="en"?"bn":"en";document.documentElement.lang=LANG;renderBar();render();return}
 if(el("#theme")){const d=document.documentElement;d.dataset.theme=(d.dataset.theme||(matchMedia("(prefers-color-scheme:dark)").matches?"dark":"light"))==="dark"?"light":"dark";renderBar();render();return}
 if((x=el("[data-more-nav]"))){document.body.insertAdjacentHTML("beforeend",`<div id="scrim"></div><nav id="more"><div class="grab"></div>${[...NAV,...NAVB,...NAV2].filter(n=>n[4]==="desk").map(([k,ic,l])=>`<a class="nav" href="#${k}"><span class="ms">${ic}</span><span>${l}</span></a>`).join("")}</nav>`);return}
 if(el("#scrim")||el("#more a")){$("#more")?.remove();$("#scrim")?.remove();return}
 if(LO&&!el(".lyr")){LO=false;render()}
 if(!el(".search"))$("#sr")&&($("#sr").hidden=true)});
document.addEventListener("input",e=>{if(e.target.id==="q")searchShow();if(e.target.id==="qf"){QF[e.target.dataset.key]=e.target.value;const p=e.target.selectionStart;render();const f=$("#qf");f.focus();f.setSelectionRange(p,p)}});
document.addEventListener("keydown",e=>{if(e.key==="Escape"){const b=$(".chart.isfull");if(b){b.classList.remove("isfull");drawChart(b,BY[b.dataset.chart])}else if($("#sr")&&!$("#sr").hidden){$("#sr").hidden=true}}
 if(e.key==="/"&&!/INPUT|TEXTAREA/.test(document.activeElement?.tagName)){e.preventDefault();$("#q").focus()}
 if(e.key==="Enter"&&e.target.matches(".lrow,tr[data-open]"))e.target.click();
 if(e.key==="Enter"&&e.target.id==="q"){const f=$("#sr [data-pick]");f&&f.click()}});
addEventListener("hashchange",()=>{$("#more")?.remove();$("#scrim")?.remove();render();scrollTo(0,0)});
renderBar();favicon();render();
